    /** Sees every screen and figure and changes nothing. */
    public static final String VIEWER = "viewer";

    private final JdbcTemplate jdbc;

    private final Sheets sheets;

    public Settings(JdbcTemplate jdbc, Sheets sheets) {
        this.jdbc = jdbc;
